// A learning workspace: each topic has its own panel; the instrument travels with you.
const topicNames=['首页','音与音程','音阶与调性','和弦构成','功能与进行','听见与应用'];
const oldHero=$('.hero'),oldJourney=$('#journey'),oldLab=$('#lab'),oldProgress=$('.progression-section'),oldDictionary=$('#dictionary');
const workspace=document.createElement('div');workspace.className='learning-workspace';
workspace.innerHTML=`<div class="workspace-tabs" role="tablist" aria-label="学习章节">${topicNames.map((n,i)=>`<button role="tab" id="topic-${i}" data-topic="${i}" aria-controls="panel-${i}">${i?'0'+i+' / ':''}${n}</button>`).join('')}</div>${topicNames.map((n,i)=>`<article role="tabpanel" id="panel-${i}" aria-labelledby="topic-${i}" class="topic-panel" hidden></article>`).join('')}`;
$('main').prepend(workspace);$('#panel-0').append(oldHero,oldJourney);$('#panel-3').append(oldLab,oldDictionary);$('#panel-4').append(oldProgress);$('.closing').remove();
const intro=(number,title,text)=>`<div class="topic-heading"><span class="eyebrow">CHAPTER ${number} / 理解，然后听见</span><h1>${title}</h1><p>${text}</p></div>`;
$('#panel-1').innerHTML=intro('01','音程，是两个音的关系。','先问“跨了几个音名”，再问“隔了几个半音”。这两个答案合起来，才是完整的音程名称。')+`<div class="reading-grid"><section class="reading-card"><span class="step-number">01</span><h2>先数音名，确定几度</h2><p>从低音到高音，按 C、D、E、F、G、A、B 的字母顺序计数，起点与终点都算在内。升降号暂时不影响度数。</p><div class="example-line">C → D → E <strong>三度</strong></div><p>C–E、C–E♭、C–E♯ 都是三度。C–D♯ 却是二度，因为只有 C、D 两个音名字母。</p></section><section class="reading-card"><span class="step-number">02</span><h2>再数半音，确定性质</h2><p>十二平均律中，琴键上相邻的两个音相距一个半音，黑键也参与计数。E–F、B–C 之间没有黑键，同样相距一个半音。</p><div class="example-line">C → E：4 半音 <strong>大三度</strong></div><p>C–E♭ 是 3 半音，叫小三度。半音数从起点走到终点，数的是“步数”，不是把两端键数相加。</p></section></div><section class="reading-card interval-experiment"><div><span class="eyebrow">INTERVAL EXPLORER</span><h2>同样从 C 出发，名字怎么变？</h2><p>选择高音，比较“音名跨度”与“实际距离”。</p></div><label>高音 <select id="intervalChoice"><option value="0">D♭</option><option value="1">D</option><option value="2">D♯</option><option value="3">E♭</option><option value="4" selected>E</option><option value="5">E♯</option><option value="6">F</option><option value="7">F♯</option><option value="8">G♭</option><option value="9">G</option><option value="10">A♭</option><option value="11">A</option><option value="12">B♭</option><option value="13">B</option><option value="14">C（高八度）</option></select></label><div id="intervalResult" aria-live="polite"></div><button class="primary" id="hearInterval">▶ 先后听，再一起听</button></section><section class="reading-card"><h2>为什么有“大三度”，却没有“纯三度”？</h2><p>音程命名采用两组基准。二、三、六、七度属于<strong>大小音程组</strong>，一、四、五、八度属于<strong>纯音程组</strong>。“纯”是命名体系中的性质，不等于更好听或更正确。</p><div class="reading-grid"><div class="rule-block"><h3>二、三、六、七度</h3><p>减 ← 小 ← 大 → 增</p><p>同一个度数里，小比大少 1 半音；减比小再少 1 半音；增比大多 1 半音。</p><p>三度例子：C–E𝄫 减三度（2）→ C–E♭ 小三度（3）→ C–E 大三度（4）→ C–E♯ 增三度（5）。</p></div><div class="rule-block"><h3>一、四、五、八度</h3><p>减 ← 纯 → 增</p><p>相对纯音程，缩小 1 半音为减，扩大 1 半音为增。纯一度向下缩小的情况超出这里的入门范围。</p><p>五度例子：C–G♭ 减五度（6）→ C–G 纯五度（7）→ C–G♯ 增五度（8）。</p></div></div></section><section class="reading-card"><h2>一张表，建立半音基准</h2><div class="table-wrap"><table><thead><tr><th>度数</th><th>基准性质与半音数</th><th>C 起点示例</th></tr></thead><tbody>${[['一度','纯一度 0','C–C'],['二度','小二度 1 / 大二度 2','C–D♭ / C–D'],['三度','小三度 3 / 大三度 4','C–E♭ / C–E'],['四度','纯四度 5','C–F'],['五度','纯五度 7','C–G'],['六度','小六度 8 / 大六度 9','C–A♭ / C–A'],['七度','小七度 10 / 大七度 11','C–B♭ / C–B'],['八度','纯八度 12','C–高音 C']].map(row=>'<tr>'+row.map(v=>`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div><div class="callout">6 半音既可能是增四度 C–F♯，也可能是减五度 C–G♭。先看字母，再数半音，才能区分。两者在十二平均律里等音，但记谱与功能语境不同。</div></section><section class="reading-card"><h2>把逻辑用起来</h2><p>问题：D–F 是什么音程？先数 D、E、F，得到三度；再数 D→D♯→E→F，共 3 半音，所以是小三度。</p><details><summary>练一练：C–D♯ 与 C–E♭ 都有 3 半音，名字一样吗？</summary><p>不一样。C–D♯ 是增二度，C–E♭ 是小三度。相同键盘音高距离，并不能单独决定音程名称。</p></details><details><summary>进阶：九度和二度是什么关系？</summary><p>超过八度的是复音程。九度可理解为二度加一个八度；大九度为 14 半音。求基本关系时可减去八度，但记谱仍保留九度名称。</p></details></section>`;
$('#panel-2').innerHTML=intro('02','音阶，是一套距离的安排。','相同的间距规律从不同根音出发，得到不同调的音阶。调性则进一步涉及音乐把哪个音、哪个和弦当作归属。')+`<section class="reading-card"><h2>用全音和半音搭出大调</h2><p>全音等于 2 个半音。大调依次使用“全、全、半、全、全、全、半”，总共 12 半音，回到高八度的主音。</p><label>主音 <select id="scaleRoot">${roots.map((r,i)=>`<option value="${i}">${r[0]} 大调</option>`).join('')}</select></label><div class="scale-notes" id="scaleNotes"></div><button class="primary" id="hearScale">▶ 听这个大调音阶</button><p>每个字母使用一次，所以 F♯ 大调的第七音要写 E♯，不能用 F 代替。</p></section><div class="reading-grid"><section class="reading-card"><h2>自然小调改变了哪些级？</h2><p>自然小调的排列是“全、半、全、全、半、全、全”。和同主音大调比较，第 3、6、7 级各降低半音。</p><div class="example-line">C 自然小调：C D E♭ F G A♭ B♭</div><p>A 自然小调与 C 大调共享自然音，但主音不同，称为关系大小调。共享音集合，不代表音乐归属相同。</p></section><section class="reading-card"><h2>音阶 ≠ 完整的调性判断</h2><p>音阶描述音的集合与顺序；调性还要从旋律重心、和声进行、终止位置等线索来听。仅凭“只用白键”不能断定是 C 大调。</p><p>小调作品还常用和声小调（升高第七级），或根据语境使用旋律小调；因此调内音也不是永远不变的限制。</p></section></div>`;
$('#panel-3').prepend(Object.assign(document.createElement('div'),{innerHTML:intro('03','和弦，把音程叠成声音。','构成音相对根音的关系，与相邻两个构成音之间的关系，要分开看。') }));
const bridge=document.createElement('section');bridge.className='reading-card';bridge.innerHTML='<h2>大三和弦：两种说法，同一个结构</h2><div class="reading-grid"><div class="rule-block"><h3>以根音为参照</h3><p>根音 ＋ 大三度 ＋ 纯五度</p><p>C–E 为大三度，C–G 为纯五度。对应距根音的半音数：0、4、7。</p></div><div class="rule-block"><h3>以相邻构成音为参照</h3><p>大三度 ＋ 小三度</p><p>C–E 为 4 半音，E–G 为 3 半音。两段距离相加，C–G 为 7 半音。</p></div></div><p>“根音＋大三度＋纯五度”中的各音程均从根音出发，并不是先走大三度，再继续走纯五度。</p>';$('#panel-3').insertBefore(bridge,oldLab);
$('#panel-4').prepend(Object.assign(document.createElement('div'),{innerHTML:intro('04','功能，让和弦有了语境。','同一个和弦在不同调里，可以承担不同角色。先确定调，再讨论级数与功能。') }));
$('#panel-4').insertAdjacentHTML('beforeend',`<section class="reading-card"><h2>C 大调里的七个三和弦</h2><p>在音阶每个音上按三度叠加：I C，ii Dm，iii Em，IV F，V G，vi Am，vii° Bdim。大写表示大三和弦，小写表示小三和弦，° 表示减三和弦。</p><div class="reading-grid"><div class="rule-block"><h3>主 → 下属 → 属 → 主</h3><p>以 I–IV–V–I 为例，C → F → G → C，形成从稳定、展开、张力到回归的常见走向。</p></div><div class="rule-block"><h3>为什么 G7 容易走向 C？</h3><p>G7 中的 B 常上行到 C，F 常下行到 E。声部的小距离移动，让张力获得解决。这是常见倾向，并非强制规则。</p></div></div><p>流行循环、布鲁斯、调式音乐也有各自的组织方式，不能把全部音乐都套进同一个功能模型。</p></section>`);
$('#panel-5').innerHTML=intro('05','把名字，变成耳朵里的经验。','一轮只比较一个变量：先听，再看公式，最后亲手弹一次。右下角的小钢琴在每个章节都能打开。')+`<div class="reading-grid"><section class="reading-card"><h2>01 / 比较三音</h2><p>依次听 C 大三和弦与 C 小三和弦。根音 C、五音 G 不变，只把 E 降为 E♭。</p><button class="primary" id="compareThird">▶ 对比大三 / 小三</button><p id="compareStatus" role="status">听音提示：留意中间的那个音，不急着给声音贴情绪标签。</p></section><section class="reading-card"><h2>02 / 在琴上重建结构</h2><p>打开小钢琴，在 C4、E4、G4 上同时按下。电脑可按 A、D、G；触屏可用三个手指。然后改成 A、S、G，比较挂二和弦。</p><button class="primary" id="practicePiano">打开小钢琴 ↗</button></section></div><section class="reading-card"><h2>03 / 给自己一个听音任务</h2><p>听两个音，判断第二个音与 C 的距离，再打开答案。</p><button class="primary" id="quizPlay">▶ 听题目</button><details id="quizAnswer"><summary>查看答案与推导</summary><p>C–G，纯五度：数 C、D、E、F、G 得五度，实际距离为 7 半音。</p></details><p>这里先固定 C 为低音、纯五度为练习对象。熟悉后可以在音程章节切换更多音程对照聆听。</p></section>`;
function switchTopic(i,updateHash=true){i=Math.max(0,Math.min(5,i));$$('[role=tabpanel]').forEach((p,j)=>p.hidden=i!==j);$$('[data-topic]').forEach((b,j)=>{b.setAttribute('aria-selected',i===j);b.tabIndex=i===j?0:-1});if(updateHash)history.replaceState(null,'','#topic-'+i);window.scrollTo({top:0,behavior:'instant'});}
$$('[data-topic]').forEach(b=>{b.onclick=()=>switchTopic(+b.dataset.topic);b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=+b.dataset.topic;i=e.key==='Home'?0:e.key==='End'?5:(i+(e.key==='ArrowRight'?1:5))%6;switchTopic(i);$('#topic-'+i).focus()}}});
$$('nav a').forEach((a,i)=>{a.textContent=['学习章节','和弦实验','和弦速查'][i];a.onclick=e=>{e.preventDefault();switchTopic(i?3:1);if(i===2)oldDictionary.scrollIntoView()}});
$$('[data-lesson]').forEach((b,i)=>b.addEventListener('click',()=>switchTopic(i+1)));$$('a[href="#lab"]').forEach(a=>a.onclick=e=>{e.preventDefault();switchTopic(3)});$$('a[href="#journey"]').forEach(a=>a.onclick=e=>{e.preventDefault();switchTopic(1)});
const originalRender=render;render=function(){originalRender();let el=$('#intervalTags');if(!el){el=document.createElement('div');el.id='intervalTags';$('#formula').after(el)}el.innerHTML=`<div class="interval-tags">${selected.labels.map((l,i)=>`<span><strong>${l}</strong><small>${i?'距根音 '+selected.intervals[i]+' 半音':'参照点 · 0 半音'}</small></span>`).join('<b>＋</b>')}</div><p class="interval-reference">以上音程全部相对根音 · 相邻构成音间距：${selected.intervals.slice(1).map((v,i)=>v-selected.intervals[i]).join(' ＋ ')} 半音</p>`;};
const intervalExamples=[['D♭',1,'小二度','二'],['D',2,'大二度','二'],['D♯',3,'增二度','二'],['E♭',3,'小三度','三'],['E',4,'大三度','三'],['E♯',5,'增三度','三'],['F',5,'纯四度','四'],['F♯',6,'增四度','四'],['G♭',6,'减五度','五'],['G',7,'纯五度','五'],['A♭',8,'小六度','六'],['A',9,'大六度','六'],['B♭',10,'小七度','七'],['B',11,'大七度','七'],['高音 C',12,'纯八度','八']];
function intervalUpdate(){const x=intervalExamples[+$('#intervalChoice').value];$('#intervalResult').innerHTML=`<div class="interval-tags"><span><strong>C → ${x[0]}</strong><small>起音 → 高音</small></span><span><strong>${x[3]}度</strong><small>音名字母跨度</small></span><span><strong>${x[1]} 半音</strong><small>实际距离</small></span><span><strong>${x[2]}</strong><small>完整名称</small></span></div>`}$('#intervalChoice').onchange=intervalUpdate;$('#hearInterval').onclick=async()=>{const n=60+intervalExamples[+$('#intervalChoice').value][1];sound([60,n],.5);setTimeout(()=>sound([60,n]),1400)};intervalUpdate();
const majorSteps=[0,2,4,5,7,9,11,12];function scaleUpdate(){const r=roots[+$('#scaleRoot').value];$('#scaleNotes').innerHTML=majorSteps.map((v,i)=>{const letter=letters[(letters.indexOf(r[0][0])+i)%7];let d=((r[1]+v-natural[letter]+18)%12)-6;return `<span>${letter+({[-2]:'𝄫',[-1]:'♭',0:'',1:'♯',2:'𝄪'}[d])}<small>${i+1}${i===7?' / 八度':''}</small></span>`}).join('')}$('#scaleRoot').onchange=scaleUpdate;$('#hearScale').onclick=()=>sound(majorSteps.map(v=>60+roots[+$('#scaleRoot').value][1]+v),.3);scaleUpdate();
$('#compareThird').onclick=async()=>{$('#compareStatus').textContent='先听 C 大三，再听 C 小三：E → E♭';sound([60,64,67]);setTimeout(()=>sound([60,63,67]),2000)};$('#quizPlay').onclick=()=>{$('#quizAnswer').open=false;sound([60,67],.7)};
// Polyphonic live instrument. One voice per input, released by pointer/key lifecycle.
const dock=document.createElement('aside');dock.className='piano-dock';dock.innerHTML=`<button id="pianoToggle" aria-expanded="false" aria-controls="pianoPanel"><span class="mini-piano">▥</span> 小钢琴 <small>随时弹一弹</small></button><div id="pianoPanel" hidden><div class="piano-toolbar"><div><strong>随身小钢琴</strong><small>多音演奏 · 按住发声，松开释音</small></div><button id="octDown" aria-label="降低八度">− 八度</button><span id="octLabel">C4–E5</span><button id="octUp" aria-label="升高八度">＋ 八度</button><button id="pianoClose" aria-label="关闭小钢琴">✕</button></div><div class="live-keyboard" id="liveKeyboard"></div><div class="piano-help"><span>白键 A S D F G H J K L　黑键 W E T Y U O P</span><span>Z / X 切换八度 · 手机 / 平板支持多指同时弹奏</span></div><p id="liveStatus" role="status">从 C4 出发，试着同时按 A、D、G。</p></div>`;document.body.append(dock);
let octave=4;const keyCodes=['KeyA','KeyW','KeyS','KeyE','KeyD','KeyF','KeyT','KeyG','KeyY','KeyH','KeyU','KeyJ','KeyK','KeyO','KeyL','KeyP','Semicolon'];const keyHints=['A','W','S','E','D','F','T','G','Y','H','U','J','K','O','L','P',';'];const voices=new Map(),held=new Set();
function pianoKeys(){let whites=0;$('#liveKeyboard').innerHTML=keyCodes.map((code,i)=>{const black=[1,3,6,8,10].includes(i%12),pos=whites;if(!black)whites++;return `<button class="live-key ${black?'black':'white'}" data-offset="${i}" style="${black?'left:calc('+pos+' * 10% - 3%)':''}" aria-label="${roots.find(r=>r[1]===i%12)[0]}${octave+Math.floor(i/12)}"><span>${roots.find(r=>r[1]===i%12)[0]}${octave+Math.floor(i/12)}</span><kbd>${keyHints[i]}</kbd></button>`}).join('');$('#octLabel').textContent=`C${octave}–E${octave+1}`}
function liveVisual(){const active=[...voices.values()];$$('.live-key').forEach(k=>k.classList.toggle('held',active.some(v=>v.offset===+k.dataset.offset)));$('#liveStatus').textContent=active.length?'正在弹奏：'+[...new Set(active.map(v=>v.name))].join(' · '):'按住琴键持续发声，松开停止。'}
async function noteOn(id,offset){if(held.has(id))return;held.add(id);try{await audio();if(!held.has(id))return;const midi=(octave+1)*12+offset,t=ctx.currentTime,g=ctx.createGain();g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.065,t+.015);g.connect(ctx.destination);const oscs=[1,2,3].map((h,i)=>{const o=ctx.createOscillator(),a=ctx.createGain();o.frequency.value=440*2**((midi-69)/12)*h;a.gain.value=[1,.22,.06][i];o.connect(a);a.connect(g);o.start();return o});voices.set(id,{g,oscs,offset,name:roots.find(r=>r[1]===midi%12)[0]+(Math.floor(midi/12)-1)});liveVisual()}catch{held.delete(id);$('#liveStatus').textContent='声音未能开启，请检查浏览器音频权限。'}}
function noteOff(id){held.delete(id);const v=voices.get(id);if(!v)return;const t=ctx.currentTime;v.g.gain.cancelScheduledValues(t);v.g.gain.setTargetAtTime(0,t,.04);v.oscs.forEach(o=>o.stop(t+.25));setTimeout(()=>v.g.disconnect(),300);voices.delete(id);liveVisual()}
function releaseAll(){[...held].forEach(noteOff)}function openPiano(open){$('#pianoPanel').hidden=!open;$('#pianoToggle').setAttribute('aria-expanded',open);if(!open)releaseAll()}
$('#pianoToggle').onclick=()=>openPiano($('#pianoPanel').hidden);$('#pianoClose').onclick=()=>openPiano(false);$('#practicePiano').onclick=()=>openPiano(true);
function changeOctave(delta){releaseAll();octave=Math.max(1,Math.min(6,octave+delta));pianoKeys()}$('#octDown').onclick=()=>changeOctave(-1);$('#octUp').onclick=()=>changeOctave(1);
$('#liveKeyboard').onpointerdown=e=>{const k=e.target.closest('[data-offset]');if(!k)return;e.preventDefault();k.setPointerCapture(e.pointerId);noteOn('pointer-'+e.pointerId,+k.dataset.offset)};['pointerup','pointercancel','lostpointercapture'].forEach(type=>$('#liveKeyboard').addEventListener(type,e=>noteOff('pointer-'+e.pointerId)));
document.addEventListener('keydown',e=>{if($('#pianoPanel').hidden||e.isComposing||e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,select,textarea,[contenteditable=true]'))return;const i=keyCodes.indexOf(e.code);if(i>=0){e.preventDefault();if(!e.repeat)noteOn(e.code,i)}else if(!e.repeat&&['KeyZ','KeyX'].includes(e.code)){e.preventDefault();changeOctave(e.code==='KeyZ'?-1:1)}});document.addEventListener('keyup',e=>noteOff(e.code));window.addEventListener('blur',releaseAll);document.addEventListener('visibilitychange',()=>{if(document.hidden)releaseAll()});pianoKeys();
// Enable direct multitouch on the chapter keyboard too.
$('#keyboard').onclick=null;$('#keyboard').onpointerdown=e=>{const k=e.target.closest('[data-midi]');if(!k)return;e.preventDefault();k.setPointerCapture(e.pointerId);noteOn('chapter-'+e.pointerId,+k.dataset.midi-(octave+1)*12)};['pointerup','pointercancel','lostpointercapture'].forEach(t=>$('#keyboard').addEventListener(t,e=>noteOff('chapter-'+e.pointerId)));
const originalTable=table;table=function(){originalTable();$$('#chordTable tr').forEach(row=>{const id=row.querySelector('[data-explore]')?.dataset.explore,c=chords.find(c=>c.id===id);if(c){const label=document.createElement('small');label.className='table-intervals';label.textContent=c.labels.join(' ＋ ');row.cells[2].append(label)}})};table();
const initialHash=location.hash;switchTopic(/^#topic-\d$/.test(initialHash)?+initialHash.slice(-1):initialHash==='#lab'||initialHash==='#dictionary'?3:0,false);render();
